"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["29221"],{28719(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.documento_exigido.ponto_resolucao_fora_do_cronograma","status":422,"titulo":"A fase em que o fato citado na condi\xe7\xe3o de aplica\xe7\xe3o \xe9 conhecido n\xe3o pertence ao cronograma deste processo"},"descricao":{"codigo":"uniplus.selecao.documento_exigido.ponto_resolucao_fora_do_cronograma","requisitos":[],"oQueAconteceu":["O cat\xe1logo de fatos situa cada fato numa fase em que ele passa a ser conhecido (o ponto de\\nresolu\xe7\xe3o). H\xe1 um fato cuja fase n\xe3o est\xe1 no cronograma deste\\nprocesso, e o sistema n\xe3o consegue dizer quando o fato \xe9 conhecido nem se ele j\xe1 o \xe9 na fase\\ndo documento.","O erro aparece em dois grupos de opera\xe7\xf5es:","- na defini\xe7\xe3o dos documentos exigidos e na aplica\xe7\xe3o de um modelo de formul\xe1rio, a confer\xeancia\\n  das condi\xe7\xf5es de cada exig\xeancia l\xea o cat\xe1logo de fatos;\\n- na publica\xe7\xe3o e na retifica\xe7\xe3o em ato \xfanico, a\\n  confer\xeancia dos fatos das condi\xe7\xf5es repete essa leitura com o cat\xe1logo. Nelas, o mesmo erro\\n  tamb\xe9m aparece quando o fato que decide quem recebe o b\xf4nus regional \xe9 conhecido numa fase\\n  que o cronograma n\xe3o tem.","Quando a fase do fato est\xe1 no cronograma, a confer\xeancia segue para os erros\\n[`fato_resolvido_em_fase_posterior`](/erros/uniplus.selecao.documento_exigido.fato_resolvido_em_fase_posterior)\\ne\\n[`fato_da_isencao_em_outra_finalidade`](/erros/uniplus.selecao.documento_exigido.fato_da_isencao_em_outra_finalidade)."],"comoResolver":["A mensagem de detalhe diz: \\"O fato \'*c\xf3digo do fato*\' resolve na fase \'*c\xf3digo da fase*\', que n\xe3o\\npertence ao cronograma deste processo.\\" Ela nomeia o fato e a fase em que o cat\xe1logo o situa. Em qualquer caso, incluir\\nessa fase no cronograma do processo resolve. A outra sa\xedda depende da causa:","- fato citado na condi\xe7\xe3o de um documento exigido: troque a condi\xe7\xe3o por um fato conhecido numa\\n  fase que o processo tem;\\n- fato que decide quem recebe o b\xf4nus regional (s\xf3 nos congelamentos): trocar a condi\xe7\xe3o de\\n  qualquer exig\xeancia n\xe3o resolve; troque o fato de elegibilidade na configura\xe7\xe3o do b\xf4nus\\n  regional do processo.","Depois, repita a opera\xe7\xe3o."],"ondeAparece":["Defini\xe7\xe3o de documentos exigidos do processo seletivo","Aplica\xe7\xe3o de modelo de formul\xe1rio","Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Documento exigido"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);